//! C ABI over the Rust core. C-style names are intentional.
#![allow(non_camel_case_types)]

//! (generated by cbindgen via build.rs). Handles are opaque; every fallible
//! call returns `m2v_status` and records a thread-local message readable with
//! `m2v_last_error()`. Completion callbacks run on the queue's waiter thread.

use std::cell::RefCell;
use std::ffi::{c_char, CStr, CString};
use std::sync::Arc;
use std::time::Duration;

use crate::{
    CommandBuffer, ConstantValue, Device, Encoder, Event, Library, Pipeline, Queue, TimestampPool,
};

/// Status codes: OK, generic error (incl. Vulkan failures), unsupported
/// capability, invalid input.
#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum m2v_status {
    OK = 0,
    ERROR = 1,
    UNSUPPORTED = 2,
    INVALID = 3,
}

#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct m2v_device_info {
    pub subgroup_size: u32,
    pub max_threads_per_threadgroup: u32,
    pub max_shared_memory: u32,
    pub has_coopmat: bool,
    pub has_timeline: bool,
    pub total_memory: u64,
    pub gpu_core_count: u32,
}

#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum m2v_constant_kind {
    BOOL = 0,
    U32 = 1,
    I32 = 2,
    F32 = 3,
}

#[repr(C)]
#[derive(Clone, Copy)]
pub union m2v_constant_value {
    pub b: u32,
    pub u: u32,
    pub i: i32,
    pub f: f32,
}

#[repr(C)]
#[derive(Clone, Copy)]
pub struct m2v_constant {
    pub index: u32,
    pub kind: m2v_constant_kind,
    pub value: m2v_constant_value,
}

impl From<m2v_constant> for (u32, ConstantValue) {
    fn from(c: m2v_constant) -> Self {
        let value = unsafe {
            match c.kind {
                m2v_constant_kind::BOOL => ConstantValue::Bool(c.value.b != 0),
                m2v_constant_kind::U32 => ConstantValue::U32(c.value.u),
                m2v_constant_kind::I32 => ConstantValue::I32(c.value.i),
                m2v_constant_kind::F32 => ConstantValue::F32(c.value.f),
            }
        };
        (c.index, value)
    }
}

/// Opaque handle types. All are `Arc<...>` under the hood except the encoder,
/// which owns its recording session.
macro_rules! opaque {
    ($name:ident) => {
        #[repr(C)]
        pub struct $name {
            _unused: [u8; 0],
            _marker: std::marker::PhantomData<(*mut u8, std::marker::PhantomPinned)>,
        }
    };
}

opaque!(m2v_device);
opaque!(m2v_buffer);
opaque!(m2v_library);
opaque!(m2v_pipeline);
opaque!(m2v_queue);
opaque!(m2v_cmdbuf);
opaque!(m2v_event);
opaque!(m2v_encoder);
opaque!(m2v_timestamp_pool);

/// Completion callback: (error_status, gpu_start_ns, gpu_end_ns, user). Runs
/// once, on the queue's waiter thread, after the fence is signalled.
pub type m2v_completion_fn =
    extern "C" fn(m2v_status, u64, u64, *mut std::ffi::c_void);

thread_local! {
    static LAST_ERROR: RefCell<Option<CString>> = const { RefCell::new(None) };
    static NAME_CACHE: RefCell<Option<CString>> = const { RefCell::new(None) };
}

fn set_last_error(e: &crate::Error) {
    let msg = CString::new(e.to_string()).unwrap_or_else(|_| CString::new("m2v error").unwrap());
    LAST_ERROR.with(|c| *c.borrow_mut() = Some(msg));
}

fn fail(e: &crate::Error) -> m2v_status {
    set_last_error(e);
    match e {
        crate::Error::Unsupported(_) => m2v_status::UNSUPPORTED,
        crate::Error::Invalid(_) => m2v_status::INVALID,
        crate::Error::Refused(_) => m2v_status::UNSUPPORTED,
        crate::Error::Vulkan(_) => m2v_status::ERROR,
    }
}

fn status_of(r: crate::Result<()>) -> m2v_status {
    match r {
        Ok(()) => m2v_status::OK,
        Err(e) => fail(&e),
    }
}

// handle conversion helpers: raw pointers carry Arc<T> (or Encoder) boxes
macro_rules! conv {
    ($c:ty, $r:ty, $from:ident, $into:ident, $drop:ident) => {
        unsafe fn $from<'a>(p: *mut $c) -> &'a $r {
            &*(p as *mut $r)
        }
        fn $into(a: $r) -> *mut $c {
            Box::into_raw(Box::new(a)) as *mut $c
        }
        unsafe fn $drop(p: *mut $c) {
            if !p.is_null() {
                drop(Box::from_raw(p as *mut $r));
            }
        }
    };
}

conv!(m2v_device, Arc<Device>, device_ref, device_into, device_drop);
conv!(m2v_buffer, Arc<crate::Buffer>, buffer_ref, buffer_into, buffer_drop);
conv!(m2v_library, Arc<Library>, library_ref, library_into, library_drop);
conv!(m2v_pipeline, Arc<Pipeline>, pipeline_ref, pipeline_into, pipeline_drop);
conv!(m2v_queue, Arc<Queue>, queue_ref, queue_into, queue_drop);
conv!(m2v_cmdbuf, CommandBuffer, cmdbuf_ref, cmdbuf_into, cmdbuf_drop);
conv!(m2v_event, Arc<Event>, event_ref, event_into, event_drop);
conv!(m2v_timestamp_pool, TimestampPool, pool_ref, pool_into, pool_drop);
// Encoder is not Clone: stored as Box<Encoder>
unsafe fn encoder_mut<'a>(p: *mut m2v_encoder) -> &'a mut Encoder {
    &mut *(p as *mut Encoder)
}
fn encoder_into(e: Encoder) -> *mut m2v_encoder {
    Box::into_raw(Box::new(e)) as *mut m2v_encoder
}
unsafe fn encoder_drop(p: *mut m2v_encoder) {
    if !p.is_null() {
        drop(Box::from_raw(p as *mut Encoder));
    }
}

/// Library version string (static, no free needed).
#[no_mangle]
pub extern "C" fn m2v_version() -> *const c_char {
    concat!(env!("CARGO_PKG_VERSION"), "\0").as_ptr() as *const c_char
}

/// Last error message for this thread, or NULL. Valid until the next call on
/// the thread that fails something.
#[no_mangle]
pub extern "C" fn m2v_last_error() -> *const c_char {
    LAST_ERROR.with(|c| {
        c.borrow()
            .as_ref()
            .map(|s| s.as_ptr())
            .unwrap_or(std::ptr::null())
    })
}

/// First compute-capable Vulkan device (`M2V_DEVICE=<index>` selects).
#[no_mangle]
pub unsafe extern "C" fn m2v_device_new(out: *mut *mut m2v_device) -> m2v_status {
    match Device::new() {
        Ok(d) => {
            *out = device_into(d);
            m2v_status::OK
        }
        Err(e) => fail(&e),
    }
}

#[no_mangle]
pub unsafe extern "C" fn m2v_device_release(d: *mut m2v_device) {
    device_drop(d);
}

/// Device name; valid until the next m2v_device_name call on this thread.
#[no_mangle]
pub unsafe extern "C" fn m2v_device_name(d: *mut m2v_device) -> *const c_char {
    let s = CString::new(device_ref(d).name()).unwrap_or_default();
    NAME_CACHE.with(|c| *c.borrow_mut() = Some(s));
    NAME_CACHE.with(|c| c.borrow().as_ref().unwrap().as_ptr())
}

#[no_mangle]
pub unsafe extern "C" fn m2v_device_info(d: *mut m2v_device, out: *mut m2v_device_info) -> m2v_status {
    let i = device_ref(d).info();
    *out = m2v_device_info {
        subgroup_size: i.subgroup_size,
        max_threads_per_threadgroup: i.max_threads_per_threadgroup,
        max_shared_memory: i.max_shared_memory,
        has_coopmat: i.has_coopmat,
        has_timeline: i.has_timeline,
        total_memory: i.total_memory,
        gpu_core_count: i.gpu_core_count,
    };
    m2v_status::OK
}

