/// Function name by index; valid until the next call on this thread.
#[no_mangle]
pub unsafe extern "C" fn m2v_library_function_name(l: *mut m2v_library, index: u32) -> *const c_char {
    let names = library_ref(l).function_names();
    let s = names
        .get(index as usize)
        .and_then(|n| CString::new(n.as_str()).ok())
        .unwrap_or_default();
    NAME_CACHE.with(|c| *c.borrow_mut() = Some(s));
    NAME_CACHE.with(|c| c.borrow().as_ref().unwrap().as_ptr())
}

#[no_mangle]
pub unsafe extern "C" fn m2v_device_create_pipeline(
    d: *mut m2v_device,
    l: *mut m2v_library,
    name: *const c_char,
    constants: *const m2v_constant,
    n_constants: usize,
    out: *mut *mut m2v_pipeline,
) -> m2v_status {
    let name = match CStr::from_ptr(name).to_str() {
        Ok(s) => s,
        Err(_) => {
            set_last_error(&crate::Error::Invalid("pipeline name is not UTF-8".into()));
            return m2v_status::INVALID;
        }
    };
    let constants: Vec<(u32, ConstantValue)> =
        std::slice::from_raw_parts(constants, n_constants).iter().map(|c| (*c).into()).collect();
    match device_ref(d).create_pipeline(library_ref(l), name, &constants) {
        Ok(p) => {
            *out = pipeline_into(p);
            m2v_status::OK
        }
        Err(e) => fail(&e),
    }
}

