/// Fill `out` (capacity `capacity`) with nanosecond timestamps; 0 = not written.
/// `*out_len` receives the pool size.
#[no_mangle]
pub unsafe extern "C" fn m2v_timestamp_pool_results(
    p: *mut m2v_timestamp_pool,
    out: *mut u64,
    capacity: u32,
    out_len: *mut u32,
) -> m2v_status {
    match pool_ref(p).results() {
        Ok(v) => {
            let n = v.len().min(capacity as usize);
            for i in 0..n {
                *out.add(i) = v[i].unwrap_or(0);
            }
            *out_len = v.len() as u32;
            m2v_status::OK
        }
        Err(e) => fail(&e),
    }
}

/// Submit in order; the callback (called once, on the queue's waiter thread)
/// receives the GPU start/end timestamps around the whole submission.
#[no_mangle]
pub unsafe extern "C" fn m2v_queue_submit(
    q: *mut m2v_queue,
    cbs: *const *mut m2v_cmdbuf,
    n: usize,
    on_complete: Option<
        extern "C" fn(m2v_status, u64, u64, *mut std::ffi::c_void),
    >,
    user: *mut std::ffi::c_void,
) -> m2v_status {
    let cbs: Vec<CommandBuffer> =
        std::slice::from_raw_parts(cbs, n).iter().map(|c| cmdbuf_ref(*c).clone()).collect();
    let refs: Vec<&CommandBuffer> = cbs.iter().collect();
    // The C callback pointer + its user data are not Send by construction;
    // the queue contract is that the callback runs exactly once on the waiter
    // thread, so moving them there is the documented behaviour.
    struct SendCb(m2v_completion_fn, *mut std::ffi::c_void);
    unsafe impl Send for SendCb {}
    let cb = on_complete.map(|f| {
        let payload = SendCb(f, user);
        Box::new(move |c: crate::Completion| {
            let payload = payload;
            let status = match &c.error {
                None => m2v_status::OK,
                Some(e) => fail(&e),
            };
            (payload.0)(status, c.gpu_start_ns, c.gpu_end_ns, payload.1);
        }) as Box<dyn FnOnce(crate::Completion) + Send>
    });
    match queue_ref(q).submit(&refs, cb) {
        Ok(()) => m2v_status::OK,
        Err(e) => fail(&e),
    }
}
